INSERT INTO cities (governorate_id, name_ar, name_en,
                    latitude, longitude, is_active, sort_order)
SELECT g.id, g.name_ar, g.name_en,
       g.latitude, g.longitude, 1, COALESCE(g.sort_order, 0)
FROM governorates g
WHERE NOT EXISTS (
